import type { ComponentType } from "react"
import * as FramerLib from "framer"

// Framer's router hook (available at runtime, not listed in the public typings)
const useRouter: () => any = (FramerLib as any).useRouter

const KEY = "jl-return"

type Spot = { path: string; y: number }

// Remember where the visitor was (page + scroll position) right before they open a project.
// The listener sits on a wrapper (display: contents keeps the layout untouched) and runs in the
// capture phase, so it fires for any click inside the card - even when the card is a component
// instance or the link is on a nested button - without interfering with the link itself.
function saveSpot() {
    try {
        const spot: Spot = { path: window.location.pathname, y: window.scrollY }
        sessionStorage.setItem(KEY, JSON.stringify(spot))
    } catch {}
}

export function withSaveReturnSpot(Component: ComponentType<any>): ComponentType {
    return (props: any) => (
        <div
            style={{ display: "contents" }}
            onPointerDownCapture={saveSpot}
            onKeyDownCapture={(event: any) => {
                if (event.key === "Enter" || event.key === " ") saveSpot()
            }}
        >
            <Component {...props} />
        </div>
    )
}

// Navigate back to the page the visitor came from using Framer's own router
// (works in Preview and on the live site), then restore their scroll position.
export function withHistoryBack(Component: ComponentType<any>): ComponentType {
    return (props: any) => {
        const router: any = useRouter()
        return (
            <Component
                {...props}
                role="button"
                tabIndex={0}
                onClick={(event: any) => {
                    event?.preventDefault?.()
                    event?.stopPropagation?.()
                    if (typeof window === "undefined") return

                    let saved: Spot | null = null
                    try {
                        saved = JSON.parse(sessionStorage.getItem(KEY) || "null")
                    } catch {}

                    const targetPath = saved?.path || "/"
                    const routes = router?.routes || {}
                    const routeId =
                        Object.keys(routes).find((id) => routes[id]?.path === targetPath) ??
                        Object.keys(routes).find((id) => routes[id]?.path === "/")

                    if (routeId && typeof router?.navigate === "function") {
                        const cover = (window as any).__jlCover
                        const go = () => {
                        if (!saved) {
                            // no saved spot -> jump to the Projects section on the home page
                            router.navigate(routeId, "projects")
                            return
                        }
                        // Navigate and pin the scroll position from the very first frame; the page wipe
                        // covers the screen while the jump to the saved spot happens.
                        router.navigate(routeId)
                        const started = performance.now()
                        const pin = () => {
                            if (window.location.pathname === targetPath) {
                                const max = Math.max(0, document.documentElement.scrollHeight - window.innerHeight)
                                const top = Math.min(saved!.y, max)
                                if (Math.abs(window.scrollY - top) > 1) {
                                    window.scrollTo({ top, behavior: "instant" as ScrollBehavior })
                                }
                            }
                            if (performance.now() - started < 700) requestAnimationFrame(pin)
                        }
                        pin()
                        requestAnimationFrame(pin)
                        }
                        // play the blue block page wipe when it is available
                        if (typeof cover === "function") cover(go)
                        else go()
                    }
                }}
            />
        )
    }
}

