import type { ComponentType } from "react"
import { useEffect, useRef } from "react"

// While the cursor is over the project row, turn vertical mouse-wheel scrolling into a smooth
// sideways glide through the projects.
//
// It never traps the page:
// - if you were already scrolling the page when the row slid under your cursor, the page keeps
//   scrolling (the row only takes over once that scroll gesture has paused), and
// - at the first or last project, the wheel goes back to scrolling the page.
const GESTURE_GAP = 220 // ms of wheel silence that ends a scroll gesture

export function withWheelScroll(Component: ComponentType<any>): ComponentType {
    return (props: any) => {
        const ref = useRef<HTMLElement | null>(null)

        useEffect(() => {
            const el = ref.current
            if (!el) return
            // opt this row out of page smooth-scroll libraries (e.g. Lenis) that listen on the window
            el.setAttribute("data-lenis-prevent", "")
            el.style.overscrollBehaviorX = "contain"
            let target = el.scrollLeft
            let frame = 0
            let stalled = 0
            let lastWheel = 0
            let gestureOwner: "page" | "row" | null = null
            let savedSnap = ""

            const stop = () => {
                if (frame) cancelAnimationFrame(frame)
                frame = 0
                stalled = 0
                el.style.scrollSnapType = savedSnap
            }

            const animate = () => {
                const diff = target - el.scrollLeft
                if (Math.abs(diff) < 1) {
                    el.scrollLeft = target
                    return stop()
                }
                const before = el.scrollLeft
                // always move at least a pixel so rounding can never freeze the glide
                const step = Math.sign(diff) * Math.max(1, Math.abs(diff) * 0.18)
                el.scrollLeft = before + step
                // if the browser refuses to move (edge, snapping, layout change), give up cleanly
                stalled = el.scrollLeft === before ? stalled + 1 : 0
                if (stalled > 3) {
                    target = el.scrollLeft
                    return stop()
                }
                frame = requestAnimationFrame(animate)
            }

            const onWheel = (event: WheelEvent) => {
                // let trackpad sideways swipes behave natively
                if (Math.abs(event.deltaX) > Math.abs(event.deltaY)) return
                const now = performance.now()
                const newGesture = now - lastWheel > GESTURE_GAP
                lastWheel = now
                if (newGesture) gestureOwner = null

                // the page was mid-scroll when the row arrived under the cursor: let it keep going
                if (gestureOwner === "page") return

                const max = el.scrollWidth - el.clientWidth
                if (max <= 0) return
                if (!frame) target = el.scrollLeft
                const delta = event.deltaMode === 1 ? event.deltaY * 32 : event.deltaY
                const atStart = target <= 1 && delta < 0
                const atEnd = target >= max - 1 && delta > 0
                // nothing left to scroll in this direction: hand the wheel back to the page
                if (atStart || atEnd) {
                    gestureOwner = "page"
                    return
                }

                gestureOwner = "row"
                event.preventDefault()
                event.stopPropagation()
                target = Math.max(0, Math.min(max, target + delta * 1.2))
                if (!frame) {
                    savedSnap = el.style.scrollSnapType
                    el.style.scrollSnapType = "none" // snapping fights the glide
                    frame = requestAnimationFrame(animate)
                }
            }

            // wheel events anywhere else on the page mark the current gesture as a page scroll
            const onPageWheel = (event: WheelEvent) => {
                if (el.contains(event.target as Node)) return
                lastWheel = performance.now()
                gestureOwner = "page"
            }

            el.addEventListener("wheel", onWheel, { passive: false })
            window.addEventListener("wheel", onPageWheel, { passive: true, capture: true })
            return () => {
                el.removeEventListener("wheel", onWheel)
                window.removeEventListener("wheel", onPageWheel, { capture: true } as any)
                stop()
            }
        }, [])

        return <Component {...props} ref={ref} />
    }
}

