import type { ComponentType } from "react"
import { useEffect, useRef } from "react"

const STYLE_ID = "jl-text-wave-style"
const CSS = `
@keyframes jl-text-wave {
    0%   { transform: translateY(0) scaleY(1); }
    4%   { transform: translateY(-0.2em) scaleY(1.06); }
    8%   { transform: translateY(0.04em) scaleY(0.97); }
    12%  { transform: translateY(0) scaleY(1); }
    100% { transform: translateY(0) scaleY(1); }
}
.jl-wave-char {
    display: inline-block;
    white-space: pre;
    transform-origin: 50% 100%;
    animation: jl-text-wave 5s cubic-bezier(0.32, 0.72, 0, 1) infinite;
    will-change: transform;
}
@media (prefers-reduced-motion: reduce) {
    .jl-wave-char { animation: none; }
}
`

// Ripples the text letter by letter when the page opens, then again every 5 seconds.
export function withWave(Component: ComponentType<any>): ComponentType {
    return (props: any) => {
        const ref = useRef<HTMLElement | null>(null)

        useEffect(() => {
            const root = ref.current
            if (!root || typeof document === "undefined") return
            if (!document.getElementById(STYLE_ID)) {
                const style = document.createElement("style")
                style.id = STYLE_ID
                style.textContent = CSS
                document.head.appendChild(style)
            }
            if (root.querySelector(".jl-wave-char")) return

            const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT)
            const textNodes: Text[] = []
            while (walker.nextNode()) textNodes.push(walker.currentNode as Text)

            let index = 0
            for (const node of textNodes) {
                const text = node.textContent || ""
                if (!text.trim()) continue
                const frag = document.createDocumentFragment()
                for (const ch of Array.from(text)) {
                    const span = document.createElement("span")
                    span.className = "jl-wave-char"
                    span.textContent = ch
                    span.style.animationDelay = (index * 0.045).toFixed(3) + "s"
                    span.setAttribute("aria-hidden", "true")
                    frag.appendChild(span)
                    index++
                }
                node.parentNode?.replaceChild(frag, node)
            }
            root.setAttribute("aria-label", textNodes.map((n) => n.textContent).join("") || root.textContent || "")
        })

        return <Component {...props} ref={ref} />
    }
}

// Same wave, plus a stacked "extruded" shadow so the tilted hero title reads as solid 3D letters
const EXTRUDE = [
    "1px 1px 0 #2B57A8",
    "2px 2px 0 #244C9A",
    "3px 3px 0 #1E428A",
    "4px 4px 0 #18377A",
    "5px 5px 0 #122D69",
    "6px 6px 0 #0D2459",
    "7px 7px 0 #091B49",
    "10px 14px 22px rgba(0, 6, 32, 0.6)",
].join(", ")

export function withWave3D(Component: ComponentType<any>): ComponentType {
    const Waved = withWave(Component)
    return (props: any) => <Waved {...props} style={{ ...props.style, textShadow: EXTRUDE }} />
}

// Pixel-font hero title with a soft dark glow that types itself out (after the loader, if it's showing).
// Hidden letters keep their space, so nothing reflows while typing.
const TYPE_STYLE_ID = "jl-type-style"
const TYPE_CSS = `
[data-jl-type], [data-jl-type] * { font-family: "Pixelify Sans", ui-monospace, monospace !important; font-style: normal !important; font-weight: 700 !important; letter-spacing: 0.01em !important; }
[data-jl-type] { text-shadow: 0 0 10px rgba(0, 0, 0, 0.55), 0 0 22px rgba(0, 0, 0, 0.35) !important; }
[data-jl-type] .jl-type-word { white-space: nowrap; }
[data-jl-type] .jl-type-char { visibility: hidden; }
[data-jl-type] .jl-type-char.on { visibility: visible; }
@media (max-width: 809.98px) { [data-jl-type], [data-jl-type] * { font-size: 36px !important; } }
@media (prefers-reduced-motion: reduce) { [data-jl-type] .jl-type-char { visibility: visible; } }
`

export function withTypeIn(Component: ComponentType<any>): ComponentType {
    return (props: any) => {
        const ref = useRef<HTMLElement | null>(null)

        useEffect(() => {
            const root = ref.current
            if (!root || typeof document === "undefined") return
            if (!document.getElementById(TYPE_STYLE_ID)) {
                const link = document.createElement("link")
                link.rel = "stylesheet"
                link.href = "https://fonts.googleapis.com/css2?family=Pixelify+Sans:wght@700&display=swap"
                document.head.appendChild(link)
                const style = document.createElement("style")
                style.id = TYPE_STYLE_ID
                style.textContent = TYPE_CSS
                document.head.appendChild(style)
            }
            root.setAttribute("data-jl-type", "")
            if (root.querySelector(".jl-type-char")) return

            const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT)
            const textNodes: Text[] = []
            while (walker.nextNode()) textNodes.push(walker.currentNode as Text)
            const label = textNodes.map((n) => n.textContent).join("")

            const chars: HTMLElement[] = []
            for (const node of textNodes) {
                const text = node.textContent || ""
                if (!text.trim()) continue
                const frag = document.createDocumentFragment()
                for (const part of text.split(/(\s+)/)) {
                    if (!part) continue
                    if (/^\s+$/.test(part)) {
                        frag.appendChild(document.createTextNode(part))
                        continue
                    }
                    const word = document.createElement("span")
                    word.className = "jl-type-word"
                    for (const ch of Array.from(part)) {
                        const span = document.createElement("span")
                        span.className = "jl-type-char"
                        span.textContent = ch
                        word.appendChild(span)
                        chars.push(span)
                    }
                    frag.appendChild(word)
                }
                node.parentNode?.replaceChild(frag, node)
            }
            root.setAttribute("aria-label", label)
            if (!chars.length) return

            if (window.matchMedia?.("(prefers-reduced-motion: reduce)").matches) {
                chars.forEach((c) => c.classList.add("on"))
                return
            }

            const timers: number[] = []
            let i = 0
            const tick = () => {
                const c = chars[i++]
                c.classList.add("on")
                if (i < chars.length) timers.push(window.setTimeout(tick, 70 + Math.random() * 50))
            }
            // wait for the intro loader to start fading out before typing
            const start = () => {
                timers.push(window.setTimeout(tick, 350))
            }
            const waitLoader = () => {
                const l = document.getElementById("jl-loader")
                if (!l || l.classList.contains("out")) start()
                else timers.push(window.setTimeout(waitLoader, 100))
            }
            waitLoader()
            return () => timers.forEach((t) => clearTimeout(t))
        }, [])

        return <Component {...props} ref={ref} />
    }
}

