float n(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);
return mix(mix(h(i),h(i+vec2(1.,0.)),f.x),mix(h(i+vec2(0.,1.)),h(i+vec2(1.,1.)),f.x),f.y);}
float fbm(vec2 p){float v=0.,a=.5;for(int i=0;i<4;i++){v+=a*n(p);p=p*2.03+vec2(1.7,9.2);a*=.5;}return v;}
void main(){
 vec2 uv=gl_FragCoord.xy/R;
 float y=1.-uv.y;
 float asp=R.x/R.y;
 vec3 top0=vec3(.05,.47,.76),mid0=vec3(.02,.27,.70),bot0=vec3(.01,.11,.52);
 vec3 top1=vec3(.01,.09,.34),bot1=vec3(.0,.02,.12);
 vec3 c0=mix(top0,mid0,smoothstep(0.,.55,y));c0=mix(c0,bot0,smoothstep(.45,1.,y));
 vec3 c1=mix(top1,bot1,smoothstep(0.,1.,y));
 vec3 col=mix(c0,c1,D);
 float surf=1.-smoothstep(0.,.3,D);
 float m=smoothstep(.45,0.,y)*surf;
 if(m>0.001){
  float k=.5+y*1.3;
  vec2 q=vec2(uv.x*asp*2.2/k,y*4.2/k);
  float w=fbm(q*.6+vec2(T*.025,-T*.015));
  float f=fbm(q*1.1+vec2(T*.035,T*.01)+vec2(w*1.2,w*.6));
  float a1=smoothstep(.56,.6,f);
  float a2=smoothstep(.63,.66,f);
  col+=vec3(.20,.62,.78)*a1*.30*m;
  col+=vec3(.35,.85,.95)*a2*.18*m;
  float g=n(vec2(uv.x*asp*55.,y*80.)+vec2(T*.7,T*.4));
  col+=vec3(.7,.95,1.)*pow(g,22.)*.25*m;
 }
 float ray=fbm(vec2(uv.x*asp*2.5+y*.8,T*.04));
 col+=vec3(.12,.30,.55)*smoothstep(.55,.85,ray)*smoothstep(.85,0.,y)*.10*(1.-D*.8);
 for(int i=0;i<18;i++){
  float fi=float(i);
  float sp=.018+h(vec2(fi,1.3))*.03;
  float r=(2.5+h(vec2(fi,3.1))*6.)*P/R.y;
  float x=h(vec2(fi,2.7))*asp;
  float yy=fract(h(vec2(fi,4.9))+T*sp+S*(.15+sp*3.));
  vec2 c=vec2(x+sin(T*.7+fi*1.7)*.012,yy*1.12-.06);
  vec2 d=vec2(uv.x*asp,uv.y)-c;
  d.x*=1.+.12*sin(T*2.+fi);
  float dist=length(d);
  float body=smoothstep(r,r*.82,dist);
  float rim=body-smoothstep(r*.82,r*.6,dist);
  float hl=smoothstep(r*.35,0.,length(d-vec2(-r*.35,r*.35)));
  float fade=smoothstep(1.02,.85,yy)*smoothstep(0.,.08,yy);
  vec3 bc=mix(vec3(.45,.80,1.),vec3(.35,.55,.95),D);
  col+=bc*(body*.10+rim*.28+hl*.35)*fade*.45;
 }
 gl_FragColor=vec4(col,1.);
}`

type Props = { style?: any }

// Same colours as the top of the water, used before the water has drawn its first frame
const GRADIENT = "linear-gradient(#0C78C2, #0545B3 55%, #031C85)"

// JS copy of the shader's hash so the overlay bubbles land exactly on the shader's bubbles
const fract = (v: number) => v - Math.floor(v)
function hash(x: number, y: number) {
    let a = fract(x * 0.1031), b = fract(y * 0.1031), c = fract(x * 0.1031)
    const d = a * (b + 33.33) + b * (c + 33.33) + c * (a + 33.33)
    a += d
    b += d
    c += d
    return fract((a + b) * c)
}
const smooth = (e0: number, e1: number, v: number) => {
    const t = Math.min(1, Math.max(0, (v - e0) / (e1 - e0)))
    return t * t * (3 - 2 * t)
}

// Draws the same bubbles again on a layer above the page, faintly, so they can be seen
// floating inside the glass boxes (where the glass blur would otherwise hide them).
const OVERLAY_STRENGTH = 1.35
function drawBubbleOverlay(ctx: CanvasRenderingContext2D, W: number, H: number, t: number, scroll: number, depth: number) {
    const dpr = ctx.canvas.width / Math.max(1, W)
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
    ctx.clearRect(0, 0, W, H)
    const asp = W / H
    const base = Math.min(window.devicePixelRatio || 1, 1.25)
    const cr = Math.round(255 * (0.72 + (0.62 - 0.72) * depth))
    const cg = Math.round(255 * (0.9 + (0.75 - 0.9) * depth))
    const cb = Math.round(255 * (1 + (0.95 - 1) * depth))
    const col = (a: number) => `rgba(${cr}, ${cg}, ${cb}, ${a})`
    for (let i = 0; i < 18; i++) {
        const sp = 0.018 + hash(i, 1.3) * 0.03
        const r = (2.5 + hash(i, 3.1) * 6) / base
        const x = hash(i, 2.7) * asp
        const yy = fract(hash(i, 4.9) + t * sp + scroll * (0.15 + sp * 3))
        const fade = smooth(1.02, 0.85, yy) * smooth(0, 0.08, yy)
        if (fade <= 0.001) continue
        const cx = (x + Math.sin(t * 0.7 + i * 1.7) * 0.012) * H
        const cy = H * (1 - (yy * 1.12 - 0.06))
        const sx = 1 / (1 + 0.12 * Math.sin(t * 2 + i))
        const k = fade * OVERLAY_STRENGTH
        ctx.save()
        ctx.translate(cx, cy)
        ctx.scale(sx, 1)
        ctx.beginPath()
        ctx.arc(0, 0, r * 0.91, 0, Math.PI * 2)
        ctx.fillStyle = col(0.1 * k)
        ctx.fill()
        ctx.beginPath()
        ctx.arc(0, 0, r * 0.8, 0, Math.PI * 2)
        ctx.lineWidth = Math.max(1, r * 0.25)
        ctx.strokeStyle = col(0.28 * k)
        ctx.stroke()
        const g = ctx.createRadialGradient(-r * 0.35, -r * 0.35, 0, -r * 0.35, -r * 0.35, r * 0.35)
        g.addColorStop(0, col(0.35 * k))
        g.addColorStop(1, col(0))
        ctx.fillStyle = g
        ctx.beginPath()
        ctx.arc(-r * 0.35, -r * 0.35, r * 0.35, 0, Math.PI * 2)
        ctx.fill()
        ctx.restore()
    }
}

function Water({ fill, overlay }: { fill: boolean; overlay: { current: HTMLCanvasElement | null } }) {
    const ref = useRef<HTMLCanvasElement>(null)
    // bumped when the phone/tablet drops the WebGL context, so the water rebuilds itself
    const [gen, setGen] = useState(0)
    useEffect(() => {
        const canvas = ref.current
        if (!canvas) return
        // alpha: anything not yet drawn shows the matching colour behind it, never black
        const gl = canvas.getContext("webgl", { antialias: false, alpha: true, powerPreference: "low-power" })
        if (!gl) return
        const backdrop = canvas.parentElement as HTMLElement | null
        const onLost = (e: Event) => {
            e.preventDefault()
            cancelAnimationFrame(raf)
            raf = 0
        }
        const onRestored = () => setGen((g) => g + 1)
        canvas.addEventListener("webglcontextlost", onLost)
        canvas.addEventListener("webglcontextrestored", onRestored)
        const sh = (type: number, src: string) => {
            const s = gl.createShader(type)!
            gl.shaderSource(s, src)
            gl.compileShader(s)
            return s
        }
        const prog = gl.createProgram()!
        gl.attachShader(prog, sh(gl.VERTEX_SHADER, VERT))
        gl.attachShader(prog, sh(gl.FRAGMENT_SHADER, FRAG))
        gl.linkProgram(prog)
        gl.useProgram(prog)
        const buf = gl.createBuffer()
        gl.bindBuffer(gl.ARRAY_BUFFER, buf)
        gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW)
        const loc = gl.getAttribLocation(prog, "p")
        gl.enableVertexAttribArray(loc)
        gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0)
        const uR = gl.getUniformLocation(prog, "R")
        const uT = gl.getUniformLocation(prog, "T")
        const uD = gl.getUniformLocation(prog, "D")
        const uS = gl.getUniformLocation(prog, "S")
        const uP = gl.getUniformLocation(prog, "P")
        let pixelScale = 1
        let raf = 0
        const reduce = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches
        // Render resolution: never above 1 canvas pixel per CSS pixel, and capped at about
        // 1080p worth of pixels; the water is soft, so this looks the same but costs far less.
        const MAX_PIXELS = 1600 * 900
        let cw = 1, ch = 1
        let ready = false
        const resize = () => {
            const w = canvas.clientWidth, h = canvas.clientHeight
            cw = w
            ch = h
            let scale = Math.min(window.devicePixelRatio || 1, 1)
            if (w * h * scale * scale > MAX_PIXELS) scale = Math.sqrt(MAX_PIXELS / (w * h))
            canvas.width = Math.max(1, Math.round(w * scale))
            canvas.height = Math.max(1, Math.round(h * scale))
            // keeps bubbles the same on-screen size as before the resolution change
            pixelScale = scale / Math.min(window.devicePixelRatio || 1, 1.25)
            gl.viewport(0, 0, canvas.width, canvas.height)
            // resizing wipes the canvas: redraw straight away so it never shows a blank frame
            if (ready) draw(performance.now())
            const ov = overlay.current
            if (ov) {
                // drawn at 1x: the slightly soft edges give the "seen through glass" look for free,
                // without a costly full-screen blur filter on every scroll frame
                const od = 1
                ov.width = Math.max(1, Math.round(w * od))
                ov.height = Math.max(1, Math.round(h * od))
            }
        }
        resize()
        const octx = overlay.current?.getContext("2d") || null
        const ro = new ResizeObserver(resize)
        ro.observe(canvas)
        // Page height is cached (reading it every frame can force extra layout work)
        let maxScroll = 1
        const measure = () => (maxScroll = Math.max(1, document.documentElement.scrollHeight - window.innerHeight))
        measure()
        const pageRo = new ResizeObserver(measure)
        pageRo.observe(document.body)
        window.addEventListener("resize", measure)
        // The water drifts slowly, so it is drawn at 30fps while idle and at full rate only
        // while the visitor scrolls (so the depth change and bubbles stay perfectly smooth).
        let lastScroll = -1e9
        const onScroll = () => (lastScroll = performance.now())
        window.addEventListener("scroll", onScroll, { passive: true })
        let shown = false
        let depth = 0, scroll = 0, lastDraw = 0, lastTick = performance.now(), lastBg = -1
        const start = performance.now()
        const frame = (now: number = performance.now()) => {
            raf = requestAnimationFrame(frame)
            const active = now - lastScroll < 400
            if (!active && now - lastDraw < 1000 / 31) return
            draw(now)
        }
        // the colour behind the canvas follows the depth, so even a skipped frame matches the water
        const mix = (a: number[], b: number[], k: number) => a.map((v, i) => Math.round(v + (b[i] - v) * k))
        const draw = (now: number) => {
            if (gl.isContextLost()) return
            const dt = Math.min(0.1, (now - lastTick) / 1000)
            lastTick = now
            lastDraw = now
            const p = Math.min(1, window.scrollY / maxScroll / 0.87)
            const target = fill ? 0 : 1 - (1 - p) * (1 - p)
            depth += (target - depth) * (1 - Math.pow(1 - 0.06, dt * 60))
            scroll += ((fill ? 0 : window.scrollY / window.innerHeight) - scroll) * (1 - Math.pow(1 - 0.08, dt * 60))
            const t = reduce ? 0 : ((now - start) / 1000) % 3600
            gl.uniform2f(uR, canvas.width, canvas.height)
            gl.uniform1f(uT, t)
            gl.uniform1f(uD, depth)
            gl.uniform1f(uS, scroll)
            gl.uniform1f(uP, pixelScale)
            gl.drawArrays(gl.TRIANGLES, 0, 3)
            if (!shown) {
                shown = true
                canvas.style.opacity = "1"
            }
            if (octx) drawBubbleOverlay(octx, cw, ch, t, scroll, depth)
            if (backdrop && Math.abs(depth - lastBg) > 0.02) {
                lastBg = depth
                const top = mix([12, 120, 194], [3, 23, 87], depth), bottom = mix([3, 28, 133], [0, 5, 31], depth)
                backdrop.style.background = `linear-gradient(rgb(${top}), rgb(${bottom}))`
            }
        }
        ready = true
        frame()
        return () => {
            cancelAnimationFrame(raf)
            ro.disconnect()
            pageRo.disconnect()
            window.removeEventListener("resize", measure)
            window.removeEventListener("scroll", onScroll)
            canvas.removeEventListener("webglcontextlost", onLost)
            canvas.removeEventListener("webglcontextrestored", onRestored)
        }
    }, [fill, gen])
    // fades in over the matching gradient once the first frame is drawn, so the load is seamless
    return <canvas ref={ref} style={{ width: "100%", height: "100%", display: "block", opacity: 0, transition: "opacity 0.35s ease-out" }} />
}

/**
 * @framerSupportedLayoutWidth any
 * @framerSupportedLayoutHeight any
 */
export default function WaterBackground(props: Props) {
    const overlay = useRef<HTMLCanvasElement>(null)
    const onCanvas = RenderTarget.current() === RenderTarget.canvas
    const [mounted, setMounted] = useState(false)
    useEffect(() => setMounted(true), [])
    if (onCanvas || !mounted) {
        return (
            <div style={{ ...props.style, width: "100%", height: "100%", background: GRADIENT }} />
        )
    }
    return (
        <>
            <div style={{ ...props.style, width: 0, height: 0 }} />
            <style>{".jl-water{position:fixed;top:0;left:0;width:100%;height:100vh;height:100lvh;pointer-events:none;contain:strict;transform:translateZ(0)}"}</style>
            {createPortal(
                <div aria-hidden className="jl-water" style={{ zIndex: -1, background: GRADIENT }}>
                    <Water fill={false} overlay={overlay} />
                </div>,
                document.body
            )}
            {createPortal(
                <canvas
                    ref={overlay}
                    aria-hidden
                    className="jl-water" style={{ zIndex: 1 }}
                />,
                document.body
            )}
        </>
    )
}

addPropertyControls(WaterBackground, {})

