import type { ComponentType } from "react"

const CYAN = "92, 225, 255"

// Tilted section heading with a slanted cyan bar behind the lower half of the text
export function withP3Heading(Component: ComponentType<any>): ComponentType {
    return (props: any) => (
        <Component
            {...props}
            style={{
                ...props.style,
                transform: "rotate(-3deg)",
                transformOrigin: "left center",
                paddingLeft: 4,
                paddingRight: 14,
                backgroundImage: `linear-gradient(105deg, transparent 0 10px, rgba(${CYAN}, 0.55) 10px calc(100% - 4px), transparent calc(100% - 4px))`,
                backgroundRepeat: "no-repeat",
                backgroundSize: "100% 42%",
                backgroundPosition: "0 92%",
                textShadow: "2px 2px 0 rgba(0, 18, 70, 0.55)",
            }}
        />
    )
}

// Slight tilt for the hero title
export function withP3Tilt(Component: ComponentType<any>): ComponentType {
    return (props: any) => (
        <Component
            {...props}
            style={{
                ...props.style,
                transform: "rotate(-4deg)",
                transformOrigin: "left center",
                textShadow: "3px 3px 0 rgba(0, 18, 70, 0.55)",
            }}
        />
    )
}

// Same look as withP3Heading, but for titles that can wrap onto several lines (project titles on
// phones): the text keeps its normal full width and the cyan bar is drawn under each line of text.
// project titles keep the tilt and shadow, without the cyan bar
const WRAP_CSS = ``

export function withP3HeadingWrap(Component: ComponentType<any>): ComponentType {
    return (props: any) => (
        <div data-jl-p3wrap="" style={{ display: "contents" }}>
            <style>{WRAP_CSS}</style>
            <Component
                {...props}
                style={{
                    ...props.style,
                    transform: "rotate(-3deg)",
                    transformOrigin: "left center",
                    textShadow: "2px 2px 0 rgba(0, 18, 70, 0.55)",
                }}
            />
        </div>
    )
}

