import { useEffect } from "react"
import { addPropertyControls } from "framer"

// Persona-style page transition: three slanted blocks sweep across the screen in one
// continuous motion. The page changes underneath while the blocks cover it, and they
// keep drifting the whole time so there is never a stop.
const COLORS = ["#061A4A", "#1565C0", "#5CE1FF"]
const DURATION = 440
const STAGGER = 30
// keyframe offsets where every block covers the screen (they slow down here but keep moving)
const COVER_AT = 0.42
const LEAVE_AT = 0.52
const SKEW = "skewX(-24deg)"

type Wipe = { root: HTMLDivElement; bars: HTMLDivElement[]; busy: boolean }

function getWipe(): Wipe {
    const w = window as any
    if (w.__jlWipe3 && document.body.contains(w.__jlWipe3.root)) return w.__jlWipe3
    const root = document.createElement("div")
    root.setAttribute("aria-hidden", "true")
    Object.assign(root.style, { position: "fixed", inset: "0", zIndex: "2147483000", pointerEvents: "none", overflow: "hidden", contain: "strict" })
    const bars: HTMLDivElement[] = []
    COLORS.forEach((color, i) => {
        const bar = document.createElement("div")
        const h = 100 / COLORS.length
        Object.assign(bar.style, {
            position: "absolute",
            left: "-25vw",
            width: "150vw",
            top: `${i * h - 1}vh`,
            height: `${h + 2}vh`,
            background: color,
            transform: `translateX(110%) ${SKEW}`,
            willChange: "transform",
            backfaceVisibility: "hidden",
        })
        // bright white light streak on the leading edge
        const edge = document.createElement("div")
        Object.assign(edge.style, {
            position: "absolute",
            left: "0",
            top: "0",
            bottom: "0",
            width: "0.8vw",
            minWidth: "6px",
            background: "#ffffff",
            boxShadow: "0 0 22px 4px rgba(255, 255, 255, 0.55)",
        })
        bar.appendChild(edge)
        root.appendChild(bar)
        bars.push(bar)
    })
    document.body.appendChild(root)
    w.__jlWipe3 = { root, bars, busy: false }
    return w.__jlWipe3
}

function coverThen(go: () => void) {
    const wipe = getWipe()
    if (wipe.busy) return
    wipe.busy = true
    wipe.root.style.pointerEvents = "auto"
    const anims = wipe.bars.map((bar, i) =>
        bar.animate(
            [
                { offset: 0, transform: `translateX(110%) ${SKEW}`, easing: "cubic-bezier(0.25, 0.8, 0.35, 1)" },
                { offset: COVER_AT, transform: `translateX(6%) ${SKEW}`, easing: "linear" },
                { offset: LEAVE_AT, transform: `translateX(-6%) ${SKEW}`, easing: "cubic-bezier(0.65, 0, 0.75, 0.2)" },
                { offset: 1, transform: `translateX(-115%) ${SKEW}` },
            ],
            { duration: DURATION, delay: i * STAGGER, fill: "both" }
        )
    )
    // navigate as soon as the blocks cover the screen; the blocks keep drifting while the new
    // page swaps in underneath
    const navAt = (wipe.bars.length - 1) * STAGGER + DURATION * COVER_AT * 0.8
    const from = window.location.pathname
    let ready = false
    window.setTimeout(() => {
        go()
        // the new page counts as ready once the address has changed and it has had two frames to paint
        const watch = () => {
            if (window.location.pathname === from) return requestAnimationFrame(watch)
            requestAnimationFrame(() => requestAnimationFrame(() => (ready = true)))
        }
        requestAnimationFrame(watch)
    }, navAt)
    // Slower devices (phones) can take a moment to build the next page. If it is not ready when the
    // blocks are about to leave, hold them in place briefly (never more than ~0.45s) so the half-built
    // page is never glimpsed. On fast devices the page is already there and nothing pauses.
    window.setTimeout(() => {
        if (ready) return
        anims.forEach((a) => a.pause())
        const started = performance.now()
        const wait = () => {
            if (!ready && performance.now() - started < 450) return requestAnimationFrame(wait)
            anims.forEach((a) => a.play())
        }
        requestAnimationFrame(wait)
    }, DURATION * LEAVE_AT)
    Promise.all(anims.map((a) => a.finished)).then(() => {
        anims.forEach((a) => a.cancel())
        wipe.root.style.pointerEvents = "none"
        wipe.busy = false
    })
}

function isTransitionLink(a: HTMLAnchorElement, event: MouseEvent) {
    if (event.defaultPrevented || event.button !== 0) return false
    if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return false
    if (a.target && a.target !== "_self") return false
    if (a.hasAttribute("download")) return false
    const raw = a.getAttribute("href") || ""
    if (!raw || raw.startsWith("#") || /^(mailto|tel|javascript):/i.test(raw)) return false
    let url: URL
    try {
        url = new URL(a.href, window.location.href)
    } catch {
        return false
    }
    if (url.origin !== window.location.origin) return false
    if (/\.(pdf|png|jpe?g|webp|svg|zip)$/i.test(url.pathname)) return false
    // same page (e.g. /#skills from home) just scrolls, no wipe
    return url.pathname !== window.location.pathname
}

// A link to the page you are already on (e.g. the home button while on the home page, no #section):
// glide back to the top instead of reloading the page onto itself.
function isSamePageTop(a: HTMLAnchorElement) {
    const raw = a.getAttribute("href") || ""
    if (!raw || raw.startsWith("#") || /^(mailto|tel|javascript):/i.test(raw)) return false
    try {
        const url = new URL(a.href, window.location.href)
        return url.origin === window.location.origin && url.pathname === window.location.pathname && !url.hash
    } catch {
        return false
    }
}
function scrollTop() {
    window.scrollTo({ top: 0, behavior: "smooth" })
}

// Follow a link after the blocks have covered the screen. Replays the gesture the site itself
// listens for (a click on desktop, a tap on touch screens), and if the page still has not
// changed shortly after, opens the link directly so a tap can never get stuck on the wipe.
function follow(a: HTMLAnchorElement, touch: boolean) {
    const w = window as any
    const from = window.location.pathname
    w.__jlBypass = true
    try {
        if (touch) {
            const r = a.getBoundingClientRect()
            const opts = { bubbles: true, cancelable: true, pointerType: "touch", isPrimary: true, pointerId: 1,
                clientX: r.left + r.width / 2, clientY: r.top + r.height / 2, button: 0 } as any
            a.dispatchEvent(new PointerEvent("pointerdown", opts))
            a.dispatchEvent(new PointerEvent("pointerup", opts))
        }
        a.click()
    } finally {
        w.__jlBypass = false
    }
    window.setTimeout(() => {
        if (window.location.pathname === from) window.location.assign(a.href)
    }, 900)
}

/**
 * @framerSupportedLayoutWidth any
 * @framerSupportedLayoutHeight any
 */
export default function PageWipe(props: { style?: any }) {
    useEffect(() => {
        const w = window as any
        if (w.__jlWipeBound) return
        if (window.matchMedia?.("(prefers-reduced-motion: reduce)").matches) return
        w.__jlWipeBound = true
        w.__jlCover = coverThen
        const onClick = (event: MouseEvent) => {
            if (w.__jlBypass) return
            const a = (event.target as Element)?.closest?.("a") as HTMLAnchorElement | null
            if (a && event.button === 0 && isSamePageTop(a)) {
                event.preventDefault()
                event.stopImmediatePropagation()
                return scrollTop()
            }
            if (!a || !isTransitionLink(a, event)) return
            event.preventDefault()
            event.stopImmediatePropagation()
            coverThen(() => follow(a, false))
        }
        // window (capture) runs before the published site's own document-level link handler
        window.addEventListener("click", onClick, true)

        // Touch screens: Framer changes page as the finger lifts (before any "click"), so catch
        // a quick tap on a link right there. Scrolls and long presses are left alone.
        let down: { x: number; y: number; t: number; id: number } | null = null
        let swallowClickUntil = 0
        window.addEventListener(
            "pointerdown",
            (e: PointerEvent) => {
                down = e.pointerType === "touch" || e.pointerType === "pen" ? { x: e.clientX, y: e.clientY, t: performance.now(), id: e.pointerId } : null
            },
            true
        )
        window.addEventListener(
            "pointerup",
            (e: PointerEvent) => {
                if (w.__jlBypass || (e.pointerType !== "touch" && e.pointerType !== "pen") || !down || down.id !== e.pointerId) return
                const isTap = Math.hypot(e.clientX - down.x, e.clientY - down.y) < 10 && performance.now() - down.t < 600
                down = null
                if (!isTap) return
                const a = (e.target as Element)?.closest?.("a") as HTMLAnchorElement | null
                if (a && isSamePageTop(a)) {
                    e.preventDefault()
                    e.stopImmediatePropagation()
                    swallowClickUntil = performance.now() + 800
                    return scrollTop()
                }
                if (!a || !isTransitionLink(a, e as unknown as MouseEvent)) return
                e.preventDefault()
                e.stopImmediatePropagation()
                swallowClickUntil = performance.now() + 800 // the browser's own click follows the tap
                coverThen(() => follow(a, true))
            },
            true
        )
        window.addEventListener(
            "click",
            (e: MouseEvent) => {
                if (!w.__jlBypass && performance.now() < swallowClickUntil) {
                    e.preventDefault()
                    e.stopImmediatePropagation()
                }
            },
            true
        )
    }, [])
    return <div style={{ ...props.style, width: 1, height: 1, pointerEvents: "none" }} />
}

