import { useEffect, useState } from "react"
// @ts-ignore
import { createPortal } from "react-dom"
import { addPropertyControls, ControlType, RenderTarget } from "framer"

// A photo album shown as a little stack of tilted prints. Hovering fans the stack out;
// clicking opens the whole album full screen (arrows / swipe to browse, Esc to close).

type Img = { src?: string; srcSet?: string; alt?: string } | string | undefined
type Props = { [key: string]: any; title?: string; flip?: boolean; style?: any }
const SLOTS = 12

const TILTS = [
    { r: -9, x: -6, y: 6 },
    { r: 7, x: 10, y: -4 },
    { r: -3, x: -2, y: -2 },
    { r: 2, x: 2, y: 0 },
]
const FAN = [
    { r: -16, x: -70, y: 14 },
    { r: 14, x: 70, y: 6 },
    { r: -5, x: -22, y: -14 },
    { r: 4, x: 20, y: -6 },
]

const src = (i: Img) => (typeof i === "string" ? i : i?.src) || ""
const alt = (i: Img, n: number, title?: string) => (typeof i === "string" ? "" : i?.alt) || `${title || "Album"} photo ${n + 1}`

const CSS = `
.jl-stack { position: relative; width: 100%; height: 100%; cursor: pointer; }
.jl-stack:focus-visible { outline: 2px solid #5CE1FF; outline-offset: 8px; border-radius: 12px; }
.jl-print { position: absolute; left: 50%; top: 50%; width: 62%; aspect-ratio: 4 / 5; border-radius: 10px; overflow: hidden;
  background: rgba(170, 215, 255, 0.14); border: 6px solid #F4F8FF; box-shadow: 0 14px 34px rgba(0, 10, 40, 0.45);
  transition: transform 0.55s cubic-bezier(0.2, 0.8, 0.2, 1); will-change: transform; }
.jl-print img { width: 100%; height: 100%; object-fit: cover; display: block; }
.jl-print.empty { border-color: rgba(255,255,255,0.35); background: rgba(170, 215, 255, 0.12); }
.jl-count { position: absolute; right: 6%; bottom: 4%; padding: 6px 12px; border-radius: 999px; font: 600 13px/1 Inter, sans-serif;
  color: #fff; background: rgba(4, 18, 60, 0.55); border: 1px solid rgba(255,255,255,0.35); z-index: 9; pointer-events: none; }
.jl-lb { position: fixed; inset: 0; z-index: 2147482000; background: rgba(2, 10, 36, 0.88); display: flex; align-items: center; justify-content: center;
  animation: jl-lb-in 0.25s ease-out; }
.jl-lb img { max-width: 88vw; max-height: 82vh; border-radius: 12px; box-shadow: 0 20px 60px rgba(0,0,0,0.5); object-fit: contain; }
.jl-lb button { position: absolute; background: rgba(170,215,255,0.14); color: #fff; border: 1px solid rgba(255,255,255,0.35);
  width: 48px; height: 48px; border-radius: 999px; font-size: 22px; cursor: pointer; }
.jl-lb .prev { left: 3vw; } .jl-lb .next { right: 3vw; } .jl-lb .close { top: 3vh; right: 3vw; }
.jl-lb .n { position: absolute; bottom: 4vh; color: #fff; font: 500 14px Inter, sans-serif; opacity: 0.8; }
@keyframes jl-lb-in { from { opacity: 0; } to { opacity: 1; } }
@media (prefers-reduced-motion: reduce) { .jl-print { transition: none; } }
`

function Lightbox({ images, start, title, onClose }: { images: Img[]; start: number; title?: string; onClose: () => void }) {
    const [i, setI] = useState(start)
    const go = (d: number) => setI((v) => (v + d + images.length) % images.length)
    useEffect(() => {
        const key = (e: KeyboardEvent) => {
            if (e.key === "Escape") onClose()
            if (e.key === "ArrowRight") go(1)
            if (e.key === "ArrowLeft") go(-1)
        }
        window.addEventListener("keydown", key)
        const prev = document.body.style.overflow
        document.body.style.overflow = "hidden"
        return () => {
            window.removeEventListener("keydown", key)
            document.body.style.overflow = prev
        }
    }, [])
    let touchX = 0
    return createPortal(
        <div
            className="jl-lb"
            role="dialog"
            aria-label={title || "Album"}
            onClick={onClose}
            onTouchStart={(e: any) => (touchX = e.touches[0].clientX)}
            onTouchEnd={(e: any) => {
                const dx = e.changedTouches[0].clientX - touchX
                if (Math.abs(dx) > 40) go(dx < 0 ? 1 : -1)
            }}
        >
            <img src={src(images[i])} alt={alt(images[i], i, title)} onClick={(e) => e.stopPropagation()} />
            {images.length > 1 && (
                <>
                    <button className="prev" aria-label="Previous photo" onClick={(e) => (e.stopPropagation(), go(-1))}>‹</button>
                    <button className="next" aria-label="Next photo" onClick={(e) => (e.stopPropagation(), go(1))}>›</button>
                </>
            )}
            <button className="close" aria-label="Close" onClick={onClose}>×</button>
            <div className="n">{i + 1} / {images.length}</div>
        </div>,
        document.body
    )
}

/**
 * @framerSupportedLayoutWidth fixed
 * @framerSupportedLayoutHeight fixed
 */
export default function PhotoStack(props: Props) {
    const images: Img[] = Array.from({ length: SLOTS }, (_, n) => props[`photo${n + 1}`]).filter((i) => !!src(i))
    const [hover, setHover] = useState(false)
    const [open, setOpen] = useState(false)
    const onCanvas = RenderTarget.current() === RenderTarget.canvas
    const shown = images.length ? images.slice(0, 4) : [undefined, undefined, undefined]
    const flip = props.flip ? -1 : 1
    return (
        <div style={{ ...props.style, position: "relative", width: "100%", height: "100%" }}>
            <style>{CSS}</style>
            <div
                className="jl-stack"
                role="button"
                tabIndex={0}
                aria-label={`Open album${props.title ? ": " + props.title : ""}`}
                onMouseEnter={() => setHover(true)}
                onMouseLeave={() => setHover(false)}
                onFocus={() => setHover(true)}
                onBlur={() => setHover(false)}
                onClick={() => images.length && !onCanvas && setOpen(true)}
                onKeyDown={(e) => (e.key === "Enter" || e.key === " ") && images.length && setOpen(true)}
            >
                {shown.map((img, n) => {
                    const t = (hover ? FAN : TILTS)[n % 4]
                    return (
                        <div
                            key={n}
                            className={"jl-print" + (img ? "" : " empty")}
                            style={{
                                zIndex: shown.length - n,
                                transform: `translate(-50%, -50%) translate(${t.x * flip}px, ${t.y}px) rotate(${t.r * flip}deg)`,
                            }}
                        >
                            {img && <img src={src(img)} alt={alt(img, n, props.title)} loading="lazy" draggable={false} />}
                        </div>
                    )
                })}
            </div>
            {open && <Lightbox images={images} start={0} title={props.title} onClose={() => setOpen(false)} />}
        </div>
    )
}

const photoControls: Record<string, any> = {}
for (let n = 1; n <= SLOTS; n++) photoControls[`photo${n}`] = { type: ControlType.ResponsiveImage, title: `Photo ${n}` }

addPropertyControls(PhotoStack, {
    title: { type: ControlType.String, title: "Album name", defaultValue: "" },
    flip: { type: ControlType.Boolean, title: "Mirror tilt", defaultValue: false },
    ...photoControls,
})

