import { addPropertyControls, ControlType } from "framer"

// Persona-style "Social Link" rank-up card: the bond bar fills, the rank ticks up with a flash,
// a star pops and "Bond deepened" slides in, then it loops. Pure CSS animation (transforms and
// opacity only), so it costs almost nothing to run.

type Props = { from?: number; to?: number; label?: string; caption?: string; style?: any }

const CSS = `
.jl-sl { position: relative; width: 100%; height: 100%; display: flex; align-items: center; font-family: Inter, sans-serif; }
.jl-sl-card { position: relative; display: flex; align-items: center; gap: 14px; padding: 10px 22px 10px 16px;
  background: linear-gradient(100deg, rgba(4, 18, 60, 0.85), rgba(11, 42, 110, 0.75)); border: 1px solid rgba(92, 225, 255, 0.55);
  box-shadow: 0 8px 24px rgba(0, 10, 40, 0.45); border-radius: 12px; overflow: hidden; }
.jl-sl-rank { position: relative; width: 52px; height: 52px; display: grid; place-items: center; }
.jl-sl-rank small { position: absolute; top: -2px; left: 0; right: 0; text-align: center; font: 700 9px/1 Inter, sans-serif; letter-spacing: 0.18em; color: #5CE1FF; }
