.jl-sl-num.a { animation: jl-sl-a 6s infinite; }
.jl-sl-num.b { animation: jl-sl-b 6s infinite; opacity: 0; }
.jl-sl-flash { position: absolute; inset: 4px; border-radius: 50%; background: radial-gradient(circle, rgba(92,225,255,0.9), rgba(92,225,255,0) 70%); opacity: 0; animation: jl-sl-flash 6s infinite; }
.jl-sl-body { display: flex; flex-direction: column; gap: 6px; min-width: 150px; }
