import { useEffect } from "react"
import { addPropertyControls } from "framer"

// Site-wide Persona touches:
// 1. Menu-style hover: a slanted cyan bar slides in behind nav links and text buttons, and
//    their text flips to dark navy (like the P3 menu cursor).
// 2. Custom cursor (mouse/trackpad only): a slanted, glowing cyan arrow drawn as a real system cursor
//    (so it moves with zero lag); over anything clickable it turns white and a spinning ring appears.

const NAVY = "#061A4A"
const CYAN = "#5CE1FF"
const BUTTONS = ["View all button", "Read more button", "See more button", "Back button", "Back link", "Resume", "Previous project", "Next project",
    "Floating email button", "Floating home button"]
const named = (n: string) => `[data-framer-name="${n}"]`
// filter chips on All projects (component variants are named Default / Active)
const CHIPS = [`[data-framer-name="Filter chips"] [data-framer-name="Default"]`, `[data-framer-name="Filter chips"] [data-framer-name="Active"]`]
// square social icon buttons in the hero
const SOCIAL = ["GitHub", "LinkedIn", "Email"].map((n) => `[data-framer-name="Social links"] [data-framer-name="${n}"]`)
const btnList = [...BUTTONS.map(named), ...CHIPS, ...SOCIAL]
const btnSel = btnList.join(",")
// text links: top menu + the contact line (email · GitHub · LinkedIn)
const navSel = `[data-framer-name="Section links"] a, [data-framer-name="Contact"] a`

// Cursor images (32x32, hotspot at the tip 6,6) with the glow baked in
const cursorSvg = (fill: string, glow: string) =>
    `url("data:image/svg+xml,${encodeURIComponent(
        `<svg xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 32 32"><defs><filter id="g" x="-50%" y="-50%" width="200%" height="200%"><feDropShadow dx="0" dy="0" stdDeviation="1.4" flood-color="${glow}" flood-opacity="1"/><feDropShadow dx="0" dy="0" stdDeviation="2.8" flood-color="${glow}" flood-opacity="0.7"/></filter></defs><g filter="url(#g)"><path d="M6 6 L26 14 L16.5 16.5 L14 26 Z" fill="${fill}"/><path d="M9.5 9.5 L20 14 L14.6 15.2" fill="none" stroke="#fff" stroke-opacity="0.75" stroke-width="1.4" stroke-linecap="round"/></g></svg>`
    )}")`
const CURSOR = cursorSvg(CYAN, CYAN)
const CURSOR_HOT = cursorSvg("#FFFFFF", "#8CEBFF")
const HOT = "a, button, [role=button], [data-framer-name$='button'], [data-framer-name='Filter chips'] [data-framer-name], .jl-stack, [data-jl-lightbox] img"

const CSS = `
${btnSel} { position: relative; isolation: isolate; overflow: hidden; }
${btnList.map((s) => s + "::before").join(",")} { content: ""; position: absolute; inset: -2px -14px; z-index: -1; background: ${CYAN};
  transform: skewX(-20deg) translateX(-115%); transition: transform 0.32s cubic-bezier(0.2, 0.8, 0.2, 1); pointer-events: none; }
${btnSel.split(",").map((s) => s + ":hover::before").join(",")} { transform: skewX(-20deg) translateX(0); }
${btnSel.split(",").map((s) => s + ":hover *").join(",")} { color: ${NAVY} !important; --framer-text-color: ${NAVY} !important; }
/* icon buttons: the white icon turns navy on the cyan */
${[...["Floating email button", "Floating home button"].map((n) => named(n) + ":hover [data-framer-name]"), ...SOCIAL.map((s) => s + ":hover > *")].join(",")} { filter: brightness(0) saturate(100%) invert(9%) sepia(60%) saturate(3500%) hue-rotate(220deg) brightness(92%) !important; }
${navSel} { position: relative; isolation: isolate; }
${navSel.split(",").map((s) => s + "::before").join(",")} { content: ""; position: absolute; inset: -3px -8px; z-index: -1; background: ${CYAN};
  transform: skewX(-20deg) scaleX(0); transform-origin: 0 50%; transition: transform 0.25s cubic-bezier(0.2, 0.8, 0.2, 1); pointer-events: none; }
${navSel.split(",").map((s) => s + ":hover::before").join(",")} { transform: skewX(-20deg) scaleX(1); }
${navSel.split(",").map((s) => s + ":hover, " + s + ":hover *").join(",")} { color: ${NAVY} !important; --framer-text-color: ${NAVY} !important; }
@media (pointer: fine) {
  html.jl-cursor, html.jl-cursor * { cursor: ${CURSOR} 6 6, auto !important; }
  html.jl-cursor :is(${HOT}), html.jl-cursor :is(${HOT}) * { cursor: ${CURSOR_HOT} 6 6, pointer !important; }
}
.jl-ring { position: fixed; left: 0; top: 0; z-index: 2147483600; pointer-events: none; will-change: transform; }
.jl-ring i { position: absolute; left: -15px; top: -15px; width: 30px; height: 30px; border-radius: 50%; box-sizing: border-box;
  border: 2.5px solid #1E428A; border-right-color: transparent; border-left-color: transparent; opacity: 0; transform: scale(0.4);
  transition: opacity 0.15s ease-out, transform 0.2s cubic-bezier(0.2, 0.8, 0.2, 1); box-shadow: 0 0 8px rgba(30, 66, 138, 0.55); }
.jl-ring.hot i { opacity: 1; transform: scale(1); animation: jl-cur-spin 1.1s linear infinite; }
@keyframes jl-cur-spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) { .jl-ring.hot i { animation: none; } }
`


/**
 * @framerSupportedLayoutWidth any
 * @framerSupportedLayoutHeight any
 */
export default function PersonaFX(props: { style?: any }) {
    useEffect(() => {
        const w = window as any
        if (w.__jlFX) return
        w.__jlFX = true
        const style = document.createElement("style")
        style.id = "jl-persona-fx"
        style.textContent = CSS
        document.head.appendChild(style)

        const fine = window.matchMedia?.("(pointer: fine)").matches
        if (!fine) return

        document.documentElement.classList.add("jl-cursor")
        // only the spinning ring is drawn by us; it follows the pointer directly in the event,
        // with no animation-frame delay
        const ring = document.createElement("div")
        ring.className = "jl-ring"
        ring.innerHTML = "<i></i>"
        document.body.appendChild(ring)
        const onMove = (e: PointerEvent) => {
            if (e.pointerType && e.pointerType !== "mouse" && e.pointerType !== "pen") return
            ring.style.transform = `translate(${e.clientX}px, ${e.clientY}px)`
        }
        const onOver = (e: PointerEvent) => {
            const t = e.target as Element | null
            ring.classList.toggle("hot", !!t?.closest?.(HOT))
        }
        window.addEventListener("pointermove", onMove, { passive: true })
        window.addEventListener("pointerover", onOver, { passive: true })
        document.addEventListener("mouseleave", () => ring.classList.remove("hot"))
    }, [])
    return <div style={{ ...props.style, width: 1, height: 1, pointerEvents: "none" }} />
}

addPropertyControls(PersonaFX, {})

