import { useEffect, useState } from "react"
import { addPropertyControls, ControlType } from "framer"

// A small terminal window that "runs" Jack's projects one after another: each command types out,
// its result appears, then the next one runs. Loops forever; cheap (a few state updates a second).

type Step = { cmd: string; out: string }
type Props = { script?: string; style?: any }

const DEFAULT_SCRIPT = [
    "idea --sketch | concept ready ✓",
    "make firmware | build passed ✓",
    "make flash | uploading to board... ✓",
    "./run | system online ✓",
].join("\n")

const parse = (s: string): Step[] =>
    s
        .split("\n")
        .map((l) => l.split("|"))
        .filter((p) => p[0].trim())
        .map(([c, o]) => ({ cmd: c.trim(), out: (o ?? "").trim() }))

type Line = { kind: "cmd" | "out"; text: string }

const CSS = `
.jl-term { width: 100%; height: 100%; box-sizing: border-box; border-radius: 12px; overflow: hidden; display: flex; flex-direction: column;
  background: rgba(3, 14, 48, 0.72); border: 1px solid rgba(92, 225, 255, 0.35); box-shadow: 0 8px 24px rgba(0, 10, 40, 0.4); }
.jl-term-bar { display: flex; align-items: center; gap: 6px; padding: 8px 12px; border-bottom: 1px solid rgba(92, 225, 255, 0.15); }
.jl-term-bar i { width: 8px; height: 8px; border-radius: 50%; background: rgba(92, 225, 255, 0.35); }
.jl-term-bar i:first-child { background: #5CE1FF; }
.jl-term-bar span { margin-left: 6px; font: 600 10px/1 Inter, sans-serif; letter-spacing: 0.12em; color: rgba(214, 232, 255, 0.55); text-transform: uppercase; }
.jl-term-body { flex: 1; padding: 10px 14px; display: flex; flex-direction: column; justify-content: flex-end; gap: 3px; overflow: hidden;
  font: 500 12.5px/1.45 ui-monospace, "SF Mono", Menlo, Consolas, monospace; }
.jl-term-line { flex-shrink: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.jl-term-cmd { color: #F0F7FF; }
.jl-term-cmd b { color: #5CE1FF; font-weight: 700; margin-right: 8px; }
.jl-term-out { color: rgba(140, 222, 255, 0.85); padding-left: 18px; }
.jl-term-caret { display: inline-block; width: 7px; height: 14px; margin-left: 2px; vertical-align: -2px; background: #5CE1FF; animation: jl-term-blink 1s steps(1) infinite; }
@keyframes jl-term-blink { 50% { opacity: 0; } }
`

/**
 * @framerSupportedLayoutWidth any
 * @framerSupportedLayoutHeight any
 */
export default function MiniTerminal(props: Props) {
    const steps = parse(props.script || DEFAULT_SCRIPT)
    const [lines, setLines] = useState<Line[]>([])
    const [typing, setTyping] = useState("")

    useEffect(() => {
        let alive = true
        const timers: number[] = []
        const wait = (ms: number) => new Promise<void>((r) => timers.push(window.setTimeout(r, ms)))
        const reduce = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches
        const run = async () => {
            if (reduce) {
                setLines(steps.flatMap((s) => [{ kind: "cmd", text: s.cmd } as Line, { kind: "out", text: s.out } as Line]))
                return
            }
            while (alive) {
                setLines([])
                for (const s of steps) {
                    for (let i = 1; i <= s.cmd.length && alive; i++) {
                        setTyping(s.cmd.slice(0, i))
                        await wait(38 + Math.random() * 30)
                    }
                    await wait(350)
                    if (!alive) return
                    setTyping("")
                    setLines((l) => [...l, { kind: "cmd", text: s.cmd }])
                    await wait(500)
                    if (s.out) setLines((l) => [...l, { kind: "out", text: s.out }])
                    await wait(1100)
                }
                await wait(1800)
            }
        }
        run()
        return () => {
            alive = false
            timers.forEach((t) => clearTimeout(t))
        }
    }, [props.script])

    return (
        <div style={{ ...props.style, width: "100%", height: "100%" }}>
            <style>{CSS}</style>
            <div className="jl-term" role="img" aria-label={"Terminal running: " + steps.map((s) => s.cmd).join(", ")}>
                <div className="jl-term-bar">
                    <i /><i /><i />
                    <span>jack@sfu: ~/projects</span>
                </div>
                <div className="jl-term-body">
                    {/* only the most recent lines; older ones scroll off the top */}
                    {lines.slice(-3).map((l, i) =>
                        l.kind === "cmd" ? (
                            <div key={i} className="jl-term-line jl-term-cmd"><b>$</b>{l.text}</div>
                        ) : (
                            <div key={i} className="jl-term-line jl-term-out">{l.text}</div>
                        )
                    )}
                    <div className="jl-term-line jl-term-cmd">
                        <b>$</b>
                        {typing}
                        <span className="jl-term-caret" />
                    </div>
                </div>
            </div>
        </div>
    )
}

addPropertyControls(MiniTerminal, {
    script: {
        type: ControlType.String,
        title: "Commands",
        displayTextArea: true,
        defaultValue: DEFAULT_SCRIPT,
        description: "One per line: command | result",
    },
})
